    text: `a = ${aVal.toFixed(1)}     h = ${hVal.toFixed(1)}     k = ${kVal.toFixed(1)}`,
    color: WHITE,
    fontSize: 23
  });
  readout.moveTo(pos);
  scene.add(readout);
}

